import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './ManageProducts.css'; // Создай или подключи стиль

const ManageProducts = () => {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    stock: '',
    category: '',
    imageUrl: '',
  });

  useEffect(() => {
    fetchProducts();
    fetchCategories();
  }, []);

  const fetchProducts = async () => {
    const res = await axios.get('/api/products');
    setProducts(res.data);
  };

  const fetchCategories = async () => {
    const res = await axios.get('/api/categories');
    setCategories(res.data);
  };

  const handleChange = (e) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/products', formData, { withCredentials: true });
      setFormData({
        name: '',
        description: '',
        price: '',
        stock: '',
        category: '',
        imageUrl: '',
      });
      fetchProducts();
    } catch (err) {
      alert('Ошибка при добавлении товара');
    }
  };

  return (
    <div className="manage-products-container">
      <h2>Управление товарами</h2>
      <form className="product-form-row" onSubmit={handleSubmit}>
        <input name="name" placeholder="Название" value={formData.name} onChange={handleChange} required />
        <input name="description" placeholder="Описание" value={formData.description} onChange={handleChange} />
        <input name="price" type="number" placeholder="Цена" value={formData.price} onChange={handleChange} required />
        <input name="stock" type="number" placeholder="Склад" value={formData.stock} onChange={handleChange} required />
        <select name="category" value={formData.category} onChange={handleChange} required>
          <option value="">Категория</option>
          {categories.map(cat => (
            <option key={cat._id} value={cat._id}>{cat.name}</option>
          ))}
        </select>
        <input name="imageUrl" placeholder="URL изображения" value={formData.imageUrl} onChange={handleChange} />
        <button type="submit">Добавить</button>
      </form>

      <ul>
        {products.map(prod => (
          <li key={prod._id}>
            <strong>{prod.name}</strong> — {prod.price} сом, Склад: {prod.stock}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ManageProducts;
